class NumArray:
    def __init__(self, nums):
        # Original nums needed for delta calculations during update
        self.nums = nums[:]   
        n = len(nums)
        # 1-indexed BIT/Fenwick tree structure
        self.bit = [0] * (n + 1)
        for i, val in enumerate(nums):
            self._add(i + 1, val)

    def update(self, index, val):
        # Compute difference 
        delta = val - self.nums[index]
        self.nums[index] = val
        # Apply difference to Fenwick Tree
        self._add(index + 1, delta)

    def sumRange(self, left, right):
        # sum(0..right) - sum(0..left-1)
        return self._prefix_sum(right + 1) - self._prefix_sum(left)

    def _add(self, i, delta):
        # Update Fenwick Tree with delta at index i
        n = len(self.bit)
        while i < n:
            self.bit[i] += delta
            i += i & -i

    def _prefix_sum(self, i):
        # Returns the sum of the first i elements (BIT indices 1..i)
        res = 0
        while i > 0:
            res += self.bit[i]
            i -= i & -i
        return res
